27	     // This mirrors applyYieldModifier in ATE's AdvancedPlanterBlockEntity. The float multiplication and
28	     // the 1.0F shortcut are kept so the count rounds the same way ATE's does.
29	     public static int ateCount(int count, float modifier) {
30	         return modifier == 1.0F ? count : Math.max(1, Math.round(count * modifier));
31	     }
