33	     // Returns the part of one drop's cloche yield bonus that ATE's rounding throws away, capped at the
34	-    // cloche's own share, in millionths of an item. The rule is in the "Built-in cloche" section of
35	+    // cloche's own share, in millionths of an item. The modifier and r stay float on purpose so r rounds
36	+    // the way ATE's count does, while the bonus math runs in double. The rule is in the "Built-in cloche" section of
37	     // docs/superpowers/specs/2026-10-28-modular-planters-design.md.
38	     public static long keptMicros(int count, float fertilizerYield, float moduleYield, double clocheYield) {
39	         float modifier = fertilizerYield * moduleYield * (float) clocheYield;
40	         int r = ateCount(count, modifier);
41	         double x = count * (double) fertilizerYield * (double) moduleYield;
42	         double e = x * clocheYield;
43	         double kept = Math.max(0, Math.min(e - r, x * (clocheYield - 1)));
44	         return Math.round(kept * RemainderLedger.ONE_ITEM);
45	     }
46	 }
