62	+        if (micros < 0) {
63	+            throw new IllegalArgumentException("micros must not be negative: " + micros);
64	+        }
65	         long total = remainders.getOrDefault(item, 0L) + micros;
66	         long whole = total / ONE_ITEM;
67	-        remainders.put(item, total - whole * ONE_ITEM);
68	+        long left = total - whole * ONE_ITEM;
69	+        if (left == 0) {
70	+            remainders.remove(item);
71	+        } else {
72	+            remainders.put(item, left);
73	+        }
74	         return (int) whole;
75	     }
76	 
77	     public Map<K, Long> snapshot() {
78	         return new HashMap<>(remainders);
79	     }
